remote_inventory.query:
begin read only; set local statement_timeout='5s'; set local lock_timeout='1s';
select now() as observed_at, n.nspname as schema, p.proname as name, pg_get_function_identity_arguments(p.oid) as arguments, p.proconfig as config, p.prosecdef as security_definer, md5(pg_get_functiondef(p.oid)) as definition_md5, has_function_privilege('anon',p.oid,'EXECUTE') as anon_execute, has_function_privilege('authenticated',p.oid,'EXECUTE') as authenticated_execute, has_function_privilege('service_role',p.oid,'EXECUTE') as service_execute, pg_get_functiondef(p.oid) as definition
from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where (n.nspname='public' and p.proname in ('catalog_embedding_candidates_v3','catalog_product_family_v1','catalog_product_variants_v1','catalog_product_identity_compatible_v1','catalog_product_identity_family_v1')) or (n.nspname='comparator_internal' and p.proname='refresh_catalog_match_cache_pair_v3') order by n.nspname,p.proname limit 10;
rollback;

