// CE-002: diagnóstico aislado del código TSX real; no renderer nativo ni red.
const fs = require('node:fs');
const vm = require('node:vm');
const cp = require('node:child_process');
const { createRequire } = require('node:module');
const localRequire = createRequire(process.cwd() + '/package.json');
const ts = localRequire('typescript');

function harness(source) {
  const slots = [], requests = [], effects = [];
  let cursor = 0, dirty = false, props, tree, closeCalls = 0;
  const context = { profile: { region: 'madrid', postalCode: '28001' }, lang: 'es' };
  const state = (initial) => {
    const i = cursor++;
    if (!(i in slots)) slots[i] = typeof initial === 'function' ? initial() : initial;
    return [slots[i], (value) => {
      const next = typeof value === 'function' ? value(slots[i]) : value;
      if (!Object.is(next, slots[i])) { slots[i] = next; dirty = true; }
    }];
  };
  const effect = (fn, deps) => {
    const i = cursor++, old = slots[i];
    if (!old || deps.some((v,j) => !Object.is(v,old.deps[j]))) {
      slots[i] = { deps, cleanup: null };
      effects.push(() => { old?.cleanup?.(); slots[i].cleanup = fn(); });
    }
  };
  const ref = initial => { const i=cursor++; return slots[i] ??= { current: initial }; };
  const element = (type, props) => ({ type, props });
  const catalog = new Proxy({}, { get: (_, name) => (...args) => new Promise((resolve,reject) => requests.push({ name, args, resolve, reject })) });
  const mockRequire = name => {
    if (name === 'react') return { useState: state, useEffect: effect, useRef: ref };
    if (name === 'react/jsx-runtime') return { jsx: element, jsxs: element };
    if (name === 'react-native') return { Modal:'Modal',View:'View',Text:'Text',TouchableOpacity:'TouchableOpacity',ActivityIndicator:'ActivityIndicator',StyleSheet:{create:x=>x} };
    if (name === '../api/catalog') return catalog;
    if (name.endsWith('/colors')) return { colors:{} };
    if (name.endsWith('/typography')) return { fonts:{} };
    if (name.endsWith('/ThemeContext')) return { useThemedStyles:fn=>fn() };
    if (name.endsWith('/LanguageContext')) return { useTranslation:()=>({t:key=>key,lang:context.lang}) };
    if (name.endsWith('/ProfileContext')) return { useProfile:()=>({profile:context.profile}) };
    if (name.endsWith('/ToastContext')) return { useToast:()=>({show:()=>{}}) };
    if (name.endsWith('/useHeaderTopPadding')) return { useHeaderTopPadding:()=>56 };
    if (name.endsWith('/useReducedMotion')) return { useReducedMotion:()=>true };
    return { default:name, __esModule:true };
  };
  const js=ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2022}}).outputText;
  const exports={};
  vm.runInNewContext(js,{exports,require:mockRequire,console});
  function pump() {
    for(let i=0;i<12;i++){
      dirty=false; cursor=0; tree=exports.default(props);
      while(effects.length)effects.shift()();
      if(!dirty)return;
    }
    throw new Error('Unexpected render loop');
  }
  return {
    requests,context,
    render(p){props={onClose:()=>closeCalls++, ...p};pump();},
    async settle(){await new Promise(resolve=>setImmediate(resolve));pump();},
    get tree(){return tree;},get closeCalls(){return closeCalls;},
  };
}
function allNodes(node,result=[]){
  if(!node||typeof node!=='object')return result;
  if(Array.isArray(node)){for(const x of node)allNodes(x,result);return result;}
  result.push(node);allNodes(node.props?.children,result);return result;
}
const productOf=h=>allNodes(h.tree).find(n=>n.props?.product)?.props.product ?? null;
const hasText=(h,t)=>allNodes(h.tree).some(n=>n.props?.children===t);
const A={store:'carrefour',id:'fixture-A'}, B={store:'carrefour',id:'fixture-B'};

async function run(source){
  const result={};
  let h=harness(source);
  h.render({target:A});
  result.loadingCloseButtons=allNodes(h.tree).filter(n=>n.type==='TouchableOpacity').length;
  h.requests[0].resolve({id:A.id,unitPrice:1});await h.settle();
  h.render({target:null});h.render({target:A});
  result.reopenWhileRefetchPendingShowsOldProduct=productOf(h)?.unitPrice===1;
  result.reopenRequestCount=h.requests.length;

  h=harness(source);h.render({target:A,fallbackToGlobalCatalog:true});
  h.render({target:null});h.requests[0].resolve(null);await h.settle();
  result.requestsAfterClosedLocalNull=h.requests.map(r=>({name:r.name,args:r.args}));

  h=harness(source);h.render({target:A});h.render({target:B});
  h.requests[1].resolve({id:B.id,unitPrice:2});await h.settle();
  h.requests[0].resolve({id:A.id,unitPrice:1});await h.settle();
  result.lateADoesNotReplaceB=productOf(h)?.id===B.id;

  h=harness(source);h.render({target:A});h.requests[0].resolve(null);await h.settle();
  result.nullDetailAutoCloseCalls=h.closeCalls;
  result.nullDetailShowsError=hasText(h,'product.detailLoadError');
  const retry=allNodes(h.tree).find(n=>n.type==='TouchableOpacity'&&allNodes(n).some(x=>x.props?.children==='common.retry'));
  retry?.props.onPress();await h.settle();
  result.retryStartsNewRequest=h.requests.length===2;

  h=harness(source);h.render({target:A,fallbackToGlobalCatalog:true});
  h.requests[0].resolve({id:A.id,unitPrice:1});await h.settle();
  h.render({target:A,fallbackToGlobalCatalog:false});
  result.policyToggleWhileRefetchPendingShowsOldProduct=productOf(h)?.unitPrice===1;
  return result;
}
(async()=>{
  const current=fs.readFileSync('src/components/StoreProductModal.tsx','utf8');
  const base=cp.execFileSync('git',['show','HEAD:src/components/StoreProductModal.tsx'],{encoding:'utf8'});
  console.log(JSON.stringify({method:'TSX real transpilado, hooks/effects y fetches simulados sin red; no renderer React Native ni prueba de dispositivo.',current:await run(current),head:await run(base)},null,2));
})().catch(error=>{console.error(error);process.exitCode=1;});
